(()=>{
const d=document.createElement('dialog');d.id='video-game-dialog';d.setAttribute('aria-labelledby','video-game-title');d.innerHTML='<button class="close-dialog" aria-label="Close game description">×</button><p class="eyebrow">IN THE GAMING ROOM</p><h2 id="video-game-title"></h2><p class="game-description"></p><small class="game-attribution"></small><a class="button primary" target="_blank" rel="noopener noreferrer">More on Steam ↗</a>';document.body.append(d);let opener;
d.querySelector('button').onclick=()=>d.close();d.addEventListener('close',()=>opener?.focus({preventScroll:true}));d.addEventListener('click',e=>{const r=d.getBoundingClientRect();if(e.target===d&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom))d.close();});
document.querySelectorAll('#steam-collection>a').forEach(card=>{const name=card.querySelector('h2').textContent;const info=window.GAME_DESCRIPTIONS.find(x=>x.name===name);card.href='#video-game-dialog';card.removeAttribute('target');card.setAttribute('role','button');card.setAttribute('aria-haspopup','dialog');card.querySelector('small').textContent='About this game ↗';card.addEventListener('click',e=>{e.preventDefault();opener=card;d.querySelector('h2').textContent=name;d.querySelector('.game-description').textContent=info.description;d.querySelector('.game-attribution').textContent=info.original?'Collection overview':'Short excerpt from the Steam store description';d.querySelector('a').href=info.url;d.showModal();});card.addEventListener('keydown',e=>{if(e.key===' '){e.preventDefault();card.click();}});});
document.addEventListener('portfolio:pagechange',()=>{if(d.open)d.close();});
})();
